import { View, Text, TouchableOpacity, TextInput, Platform } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useState } from 'react'
import { Eye, EyeOff, Copy, MoreHorizontal } from 'lucide-react-native'
import { EnvironmentTag, type Environment } from './EnvironmentTag'
import { MenuAction, MenuView } from '@react-native-menu/menu'
import * as Clipboard from 'expo-clipboard'
import * as Haptics from 'expo-haptics'
import Animated, {
	FadeIn,
	FadeOut,
	LinearTransition
} from 'react-native-reanimated'

export interface Secret {
	id: string
	name: string
	value: string
	dateAdded: string
	environments: Environment[]
}

interface SecretItemProps {
	secret: Secret
	onDelete: (id: string) => void
	onExpandedChange?: (id: string, isExpanded: boolean) => void
}

const formatDate = (dateString: string) => {
	const date = new Date(dateString)
	const month = date.getMonth() + 1
	const day = date.getDate()
	const year = date.getFullYear().toString().slice(-2)
	return `${month}/${day}/${year}`
}

const menuActions: MenuAction[] = [
	{
		id: 'delete',
		title: 'Delete Secret',
		attributes: {
			destructive: true
		},
		image: Platform.select({
			ios: 'trash',
			android: 'ic_menu_delete'
		}),
		imageColor: 'red'
	}
]

export const SecretItem = ({
	secret,
	onDelete,
	onExpandedChange
}: SecretItemProps) => {
	const { theme } = useTheme()
	const [isExpanded, setIsExpanded] = useState(false)
	const [isValueVisible, setIsValueVisible] = useState(false)

	const handleCopyToClipboard = async () => {
		await Clipboard.setStringAsync(secret.value)
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
	}

	const handlePressAction = () => {
		onDelete(secret.id)
	}

	const handlePress = () => {
		const next = !isExpanded
		setIsExpanded(next)
		onExpandedChange?.(secret.id, next)
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
	}

	return (
		<Animated.View style={styles.secretItemContainer} layout={LinearTransition}>
			<View style={styles.secretItemHeader}>
				<TouchableOpacity
					style={styles.secretItem(theme)}
					onPress={handlePress}
				>
					<Text style={styles.secretName(theme)}>{secret.name}</Text>
					<Text style={styles.dateText(theme)}>
						Added {formatDate(secret.dateAdded)}
					</Text>
				</TouchableOpacity>
				<MenuView actions={menuActions} onPressAction={handlePressAction}>
					<MoreHorizontal size={18} color={colors[theme].gray[400]} />
				</MenuView>
			</View>

			{isExpanded && (
				<Animated.View
					style={styles.expandedContent(theme)}
					entering={FadeIn}
					exiting={FadeOut}
				>
					<View style={styles.secretValueContainer(theme)}>
						<TextInput
							style={styles.secretValue(theme, isValueVisible)}
							numberOfLines={1}
							value={secret.value}
							editable={false}
							secureTextEntry={!isValueVisible}
							lineBreakModeIOS={isValueVisible ? 'middle' : 'char'}
						/>

						<View style={styles.secretActions}>
							<TouchableOpacity onPress={handleCopyToClipboard}>
								<Copy size={17} color={colors[theme].gray[400]} />
							</TouchableOpacity>
							<TouchableOpacity
								onPress={() => setIsValueVisible(!isValueVisible)}
							>
								{isValueVisible ? (
									<EyeOff size={18} color={colors[theme].gray[400]} />
								) : (
									<Eye size={18} color={colors[theme].gray[400]} />
								)}
							</TouchableOpacity>
						</View>
					</View>

					<View style={styles.environmentBadges}>
						{secret.environments.map((env) => (
							<EnvironmentTag key={env} environment={env} />
						))}
					</View>
				</Animated.View>
			)}
		</Animated.View>
	)
}

const styles = defineStyles({
	secretItemContainer: {
		paddingHorizontal: 24,
		transitionProperty: 'height',
		overflow: 'hidden'
	},
	secretItemHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		paddingVertical: 20,
		gap: 15
	},
	secretItem: (theme: Theme) => ({
		flexDirection: 'row',
		alignItems: 'center',
		flex: 1
	}),
	secretName: (theme: Theme) => ({
		fontSize: 18,
		fontWeight: '500',
		color: colors[theme].gray[900],
		flex: 1
	}),
	dateText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[400]
	}),

	expandedContent: (theme: Theme) => ({
		paddingBottom: 20,
		gap: 16
	}),
	secretValueContainer: (theme: Theme) => ({
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		gap: 10
	}),
	secretValue: (theme: Theme, isValueVisible: boolean) => ({
		fontSize: 14,
		fontWeight: '500',
		color: isValueVisible ? colors[theme].gray[900] : colors[theme].gray[400],
		fontFamily: 'monospace',
		maxWidth: '80%'
	}),
	secretActions: {
		flexDirection: 'row',
		gap: 10
	},
	environmentBadges: {
		flexDirection: 'row',
		gap: 10,
		flexWrap: 'wrap'
	}
})
